component.css:
.sb-root {
  --ink: #f6f1e6;
  --dim: rgba(246, 241, 230, 0.78);
  --gold: #ffd166;
  width: 100%;
  max-width: 360px;
  margin: 6px auto;
  position: relative;
  aspect-ratio: 1086 / 1448;
  border-radius: 14px;
  overflow: hidden;
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  color: var(--ink);
  background: #17130f;
}


.sb-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}


.sb-root::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    rgba(12, 9, 6, 0.42) 0%,
    rgba(12, 9, 6, 0.10) 22%,
    rgba(12, 9, 6, 0.10) 62%,
    rgba(12, 9, 6, 0.52) 100%
  );
  pointer-events: none;
}

.sb-top,
.sb-stage,
.sb-pager,
.sb-status {
  position: relative;
  z-index: 1;
}

.sb-data { display: none; }


.sb-top {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 7px;
  padding: 14px 14px 0;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85), 0 0 14px rgba(0, 0, 0, 0.5);
}
.sb-ico { font-size: 12px; opacity: 0.92; }
.sb-dot { opacity: 0.6; font-size: 12px; }
.sb-time {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  color: var(--gold);
  font-size: 13px;
  letter-spacing: 1px;
  white-space: nowrap;
}
.sb-loc { font-size: 13px; letter-spacing: 0.5px; }


.sb-root { display: flex; flex-direction: column; }
.sb-stage {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 13px;
  padding: 18px 18px 14px;
}
.sb-line { animation: sbIn 0.34s ease both; }
.sb-line:nth-child(2) { animation-delay: 0.07s; }
.sb-line:nth-child(3) { animation-delay: 0.14s; }
.sb-line:nth-child(4) { animation-delay: 0.21s; }
@keyframes sbIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}
.sb-back .sb-line { animation-name: sbBack; }
@keyframes sbBack {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: none; }
}


.sb-talk { text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9), 0 0 12px rgba(0, 0, 0, 0.55); }
.sb-talk .sb-name {
  color: var(--sc, var(--gold));
  font-weight: 700;
}
.sb-text {
  font-size: 14.5px;
  line-height: 1.8;
  overflow-wrap: anywhere;
  word-break: break-word;
}


.sb-narr .sb-text {
  font-style: italic;
  color: var(--dim);
}
.sb-narr { text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85); }


.sb-pager {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 4px 0 8px;
}
.sb-btn {
  width: 40px;
  height: 30px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.32);
  border: none;
  color: var(--ink);
  font-size: 11px;
  cursor: pointer;
  user-select: none;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.8);
  transition: background 0.15s, transform 0.15s;
}
.sb-btn:hover:not(:disabled) { background: rgba(0, 0, 0, 0.55); }
.sb-btn:active:not(:disabled) { transform: scale(0.93); }
.sb-btn:disabled { opacity: 0.28; cursor: default; }
.sb-pageinfo {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  color: var(--dim);
  letter-spacing: 1px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}
.sb-pageinfo b { color: var(--gold); font-size: 14px; }


.sb-status {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  padding: 0 16px 15px;
}
.sb-stat-top { display: flex; align-items: baseline; gap: 6px; margin-bottom: 5px; }
.sb-label {
  font-size: 11.5px;
  letter-spacing: 2px;
  color: var(--dim);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}
.sb-num {
  margin-left: auto;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  color: var(--ink);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}
.sb-bar {
  height: 5px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.38);
  overflow: hidden;
}
.sb-fill {
  height: 100%;
  width: 0;
  border-radius: inherit;
  transition: width 0.9s cubic-bezier(0.22, 0.9, 0.3, 1);
}
.sb-ok { background: linear-gradient(90deg, #6fd99b, #8af0b4); }
.sb-warn { background: linear-gradient(90deg, #e8a94a, #ffc861); }
.sb-danger {
  background: linear-gradient(90deg, #e05548, #ff7a6b);
  animation: sbPulse 1.6s ease-in-out infinite;
}
@keyframes sbPulse { 50% { opacity: 0.55; } }
